CREATE TABLE authz_int.shared_relations (object_type text, relation text, subject text, shared_by text, required text[], loc text, PRIMARY KEY (object_type, relation, subject));

INSERT INTO authz_int.shared_relations VALUES
  ('team', 'member', 'team#member', 'manage', ARRAY['manage', 'manage_roles']::text[], 'share team.member team#member'),
  ('project', 'viewer', 'user', 'edit', ARRAY['view']::text[], 'share project.viewer user'),
  ('project', 'viewer', 'team#member', 'edit', ARRAY['view']::text[], 'share project.viewer team#member'),
  ('project', 'viewer', 'user:*', 'edit', ARRAY['view']::text[], 'share project.viewer user:*'),
  ('project', 'viewer', 'anyone', 'edit', ARRAY['view']::text[], 'share project.viewer anyone'),
  ('project', 'viewer', 'link', 'edit', ARRAY['view']::text[], 'share project.viewer link'),
  ('folder', 'editor', 'user', 'edit', ARRAY['edit', 'view', 'share', 'peek']::text[], 'share folder.editor user'),
  ('folder', 'editor', 'team#member', 'edit', ARRAY['edit', 'view', 'share', 'peek']::text[], 'share folder.editor team#member'),
  ('folder', 'viewer', 'user', 'edit', ARRAY['view', 'peek']::text[], 'share folder.viewer user'),
  ('folder', 'viewer', 'team#member', 'edit', ARRAY['view', 'peek']::text[], 'share folder.viewer team#member'),
  ('folder', 'viewer', 'user:*', 'edit', ARRAY['view', 'peek']::text[], 'share folder.viewer user:*'),
  ('folder', 'viewer', 'link', 'edit', ARRAY['view', 'peek']::text[], 'share folder.viewer link');

DO $w$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares g WHERE g.relation NOT LIKE 'role:%' AND NOT EXISTS (
    SELECT 1 FROM authz_int.shared_relations s WHERE s.object_type = g.object_type AND s.relation = g.relation
      AND s.subject = CASE WHEN g.subject_type IN ('anyone', 'link') THEN g.subject_type
                           WHEN g.subject_id = '*' AND g.subject_relation = '' THEN g.subject_type || ':*'
                           WHEN g.subject_relation <> '' THEN g.subject_type || '#' || g.subject_relation
                           ELSE g.subject_type END);
  IF n > 0 THEN
    RAISE WARNING '% shares are for relations this policy does not declare as shared; they are kept, but grant nothing', n;
  END IF;
END $w$;

