-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND c.relname LIKE 'shares\_obj\_%'
             AND c.relname <> ALL (ARRAY['shares_obj_user_uuid', 'shares_obj_org_bigint', 'shares_obj_team_bigint', 'shares_obj_project_bigint', 'shares_obj_folder_bigint', 'shares_obj_doc_uuid']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_uuid" ON authz.shares ((object_id::uuid), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_org_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'org';
CREATE INDEX IF NOT EXISTS "shares_obj_team_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'team';
CREATE INDEX IF NOT EXISTS "shares_obj_project_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'project';
CREATE INDEX IF NOT EXISTS "shares_obj_folder_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'folder';
CREATE INDEX IF NOT EXISTS "shares_obj_doc_uuid" ON authz.shares ((object_id::uuid), relation) WHERE object_type = 'doc';

