    WHERE CASE n.t WHEN 'folder' THEN EXISTS (SELECT 1 FROM "mt"."folders" x WHERE x."id" = (CASE WHEN n.t = 'folder' THEN n.i END)::bigint) WHEN 'project' THEN EXISTS (SELECT 1 FROM "mt"."projects" x WHERE x."id" = (CASE WHEN n.t = 'project' THEN n.i END)::bigint) ELSE false END
    UNION
    SELECT up._dt, up._d, e.pt, e.p
    FROM up CROSS JOIN LATERAL (
      
SELECT 'folder'::text AS pt, ((CASE WHEN r."parent_type" = 'folder' THEN r."parent_id" END)::bigint)::text AS p FROM "mt"."folders" r WHERE r."id" = (CASE WHEN up._at = 'folder' THEN up._a END)::bigint AND (CASE WHEN r."parent_type" = 'folder' THEN r."parent_id" END)::bigint IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "mt"."folders" pp WHERE pp."id" = (CASE WHEN r."parent_type" = 'folder' THEN r."parent_id" END)::bigint AND coalesce((not archived), false))      UNION ALL SELECT 'project'::text AS pt, ((CASE WHEN r."parent_type" = 'project' THEN r."parent_id" END)::bigint)::text AS p FROM "mt"."folders" r WHERE r."id" = (CASE WHEN up._at = 'folder' THEN up._a END)::bigint AND (CASE WHEN r."parent_type" = 'project' THEN r."parent_id" END)::bigint IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "mt"."projects" pp WHERE pp."id" = (CASE WHEN r."parent_type" = 'project' THEN r."parent_id" END)::bigint)      UNION ALL SELECT 'folder'::text AS pt, (r."folder_id")::text AS p FROM "mt"."projects" r WHERE r."id" = (CASE WHEN up._at = 'project' THEN up._a END)::bigint AND r."folder_id" IS NOT NULL AND true AND EXISTS (SELECT 1 FROM "mt"."folders" pp WHERE pp."id" = r."folder_id" AND coalesce((not archived), false))) e)
  SELECT _dt, _d, _at, _a FROM up
$f$;

