               (SELECT * FROM stored EXCEPT SELECT * FROM fresh)) THEN
      RETURN false;
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM (SELECT DISTINCT dtype AS t, did AS i FROM authz_int."folder_project__parent__tree2") n
             WHERE NOT CASE n.t WHEN 'folder' THEN EXISTS (SELECT 1 FROM "mt"."folders" x WHERE x."id" = (CASE WHEN n.t = 'folder' THEN n.i END)::bigint) WHEN 'project' THEN EXISTS (SELECT 1 FROM "mt"."projects" x WHERE x."id" = (CASE WHEN n.t = 'project' THEN n.i END)::bigint) ELSE false END) THEN
    RETURN false;
  END IF;
  RETURN true;
END $f$;

-- the types' own columns may not loop (links through tables may: they add nothing)
CREATE FUNCTION authz_int."folder_project__parent__tree2_check_loops"(p_types text[], p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE bad text;
BEGIN
  -- a loop means some node reaches itself through at least one link
  WITH RECURSIVE up(_st, _s, _at, _a, _n) AS (
    SELECT x.t, x.i, x.t, x.i, 0 FROM unnest(p_types, p_ids) AS x(t, i)
    UNION
    SELECT up._st, up._s, e.pt, e.p, 1 FROM up CROSS JOIN LATERAL (
      
SELECT 'folder'::text AS pt, ((CASE WHEN r."parent_type" = 'folder' THEN r."parent_id" END)::bigint)::text AS p FROM "mt"."folders" r WHERE r."id" = (CASE WHEN up._at = 'folder' THEN up._a END)::bigint AND (CASE WHEN r."parent_type" = 'folder' THEN r."parent_id" END)::bigint IS NOT NULL      UNION ALL SELECT 'project'::text AS pt, ((CASE WHEN r."parent_type" = 'project' THEN r."parent_id" END)::bigint)::text AS p FROM "mt"."folders" r WHERE r."id" = (CASE WHEN up._at = 'folder' THEN up._a END)::bigint AND (CASE WHEN r."parent_type" = 'project' THEN r."parent_id" END)::bigint IS NOT NULL      UNION ALL SELECT 'folder'::text AS pt, (r."folder_id")::text AS p FROM "mt"."projects" r WHERE r."id" = (CASE WHEN up._at = 'project' THEN up._a END)::bigint AND r."folder_id" IS NOT NULL) e)
  SELECT _st || ' ' || _s INTO bad FROM up WHERE _n = 1 AND (_at, _a) = (_st, _s) LIMIT 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION '% cannot be moved inside itself', bad USING ERRCODE = 'check_violation', HINT = 'rowstile help AZ713';
  END IF;
END $f$;

-- folder rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder_project__parent__tree2_rows_folder"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id"::text FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    ids := ARRAY(
      SELECT n."id"::text FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."parent_id" IS DISTINCT FROM o."parent_id"
         OR n."parent_type" IS DISTINCT FROM o."parent_type"
         OR (SELECT coalesce((not archived), false) FROM (SELECT n.*) r) IS DISTINCT FROM (SELECT coalesce((not archived), false) FROM (SELECT o.*) r)
      UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
  ELSE
    ids := ARRAY(SELECT o."id"::text FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
    IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder_project__parent__tree2_check_loops"(array_fill('folder'::text, ARRAY[cardinality(ids)]), ids); END IF;
    PERFORM authz_int."folder_project__parent__tree2_refresh"(array_fill('folder'::text, ARRAY[cardinality(ids)]), ids);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_folder_ins" AFTER INSERT ON "mt"."folders"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_rows_folder"();
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_folder_upd" AFTER UPDATE ON "mt"."folders"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_rows_folder"();
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_folder_del" AFTER DELETE ON "mt"."folders"
  REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_rows_folder"();
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_folder_trunc" AFTER TRUNCATE ON "mt"."folders"
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_on_truncate"();

-- project rows inserted, deleted, moved, or whose id or conditions change
CREATE FUNCTION authz_int."folder_project__parent__tree2_rows_project"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE ids text[];
BEGIN
  IF TG_OP = 'INSERT' THEN
    ids := ARRAY(SELECT n."id"::text FROM new_rows n);
  ELSIF TG_OP = 'UPDATE' THEN
    ids := ARRAY(
      SELECT n."id"::text FROM new_rows n JOIN old_rows o ON o."id" = n."id"
      WHERE n."folder_id" IS DISTINCT FROM o."folder_id"
      UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id" = o."id")
      UNION SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id" = n."id"));
  ELSE
    ids := ARRAY(SELECT o."id"::text FROM old_rows o);
  END IF;
  IF cardinality(ids) > 0 THEN
    UPDATE authz_int.locks SET n = n + 1 WHERE type IN ('folder', 'project');
    IF TG_OP <> 'DELETE' THEN PERFORM authz_int."folder_project__parent__tree2_check_loops"(array_fill('project'::text, ARRAY[cardinality(ids)]), ids); END IF;
    PERFORM authz_int."folder_project__parent__tree2_refresh"(array_fill('project'::text, ARRAY[cardinality(ids)]), ids);
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_project_ins" AFTER INSERT ON "mt"."projects"
  REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_rows_project"();
CREATE TRIGGER "authz_folder_project__parent__tree2_rows_project_upd" AFTER UPDATE ON "mt"."projects"
  REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."folder_project__parent__tree2_rows_project"();
