-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."project__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."org_id" IS DISTINCT FROM OLD."org_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'project', NEW."id"::text, 'org', NEW."org_id"::text, jsonb_build_object('column', 'org_id', 'was', OLD."org_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."folder_id" IS DISTINCT FROM OLD."folder_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'project', NEW."id"::text, 'parent', NEW."folder_id"::text, jsonb_build_object('column', 'folder_id', 'was', OLD."folder_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."lead_id" IS DISTINCT FROM OLD."lead_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'project', NEW."id"::text, 'lead', NEW."lead_id"::text, jsonb_build_object('column', 'lead_id', 'was', OLD."lead_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_project_col_audit_row" ON "mt"."projects"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"mt"."projects"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_project_col_audit_row" AFTER UPDATE ON "mt"."projects" FOR EACH ROW WHEN (OLD."org_id" IS DISTINCT FROM NEW."org_id" OR OLD."folder_id" IS DISTINCT FROM NEW."folder_id" OR OLD."lead_id" IS DISTINCT FROM NEW."lead_id") EXECUTE FUNCTION authz_int."project__col_audit_row"()';
  ELSE
    RAISE NOTICE '"mt"."projects" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

