-- one audit row per changed relationship column (a row trigger, so it also works when the key changes)
CREATE FUNCTION authz_int."doc__col_audit_row"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NEW."container_id" IS DISTINCT FROM OLD."container_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'doc', NEW."id"::text, 'container', NEW."container_id"::text, jsonb_build_object('column', 'container_id', 'was', OLD."container_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."container_type" IS DISTINCT FROM OLD."container_type" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'doc', NEW."id"::text, 'container', NEW."container_type"::text, jsonb_build_object('column', 'container_type', 'was', OLD."container_type"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  IF NEW."author_id" IS DISTINCT FROM OLD."author_id" THEN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
    VALUES (authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'doc', NEW."id"::text, 'author', NEW."author_id"::text, jsonb_build_object('column', 'author_id', 'was', OLD."author_id"), nullif(current_setting('authz_ctx.reason', true), ''));
  END IF;
  RETURN NULL;
END $f$;
-- @object trigger "authz_doc_col_audit_row" ON "mt"."docs"
DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"mt"."docs"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_doc_col_audit_row" AFTER UPDATE ON "mt"."docs" FOR EACH ROW WHEN (OLD."container_id" IS DISTINCT FROM NEW."container_id" OR OLD."container_type" IS DISTINCT FROM NEW."container_type" OR OLD."author_id" IS DISTINCT FROM NEW."author_id") EXECUTE FUNCTION authz_int."doc__col_audit_row"()';
  ELSE
    RAISE NOTICE '"mt"."docs" is not a table: changes to it are not audited or fed (audit)';
  END IF;
END $tr$;

