  SELECT x.id FROM (
  SELECT s."org_id" AS id FROM "mt"."org_members" s WHERE s."user_id" = (SELECT authz.uid()) AND coalesce((role = 'admin'), false)) x
  WHERE EXISTS (SELECT 1 FROM "mt"."orgs" w WHERE w."id" = x.id AND coalesce((not suspended), false));

